15:  * using the Haversine formula (Earth radius 6,371,000 meters).
16:  */
17: export function calculateHaversineDistance(
18:   lat1: number,
19:   lon1: number,
20:   lat2: number,
21:   lon2: number
22: ): number {
23:   const R = 6371e3; // Earth radius in meters
24:   const φ1 = (lat1 * Math.PI) / 180;
25:   const φ2 = (lat2 * Math.PI) / 180;
26:   const Δφ = ((lat2 - lat1) * Math.PI) / 180;
27:   const Δλ = ((lon2 - lon1) * Math.PI) / 180;
28: 
29:   const a =
30:     Math.sin(Δφ / 2) * Math.sin(Δφ / 2) +
31:     Math.cos(φ1) * Math.cos(φ2) * Math.sin(Δλ / 2) * Math.sin(Δλ / 2);
32:   const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
33: 
34:   return R * c;
35: }
