'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { useLiveQuery } from 'dexie-react-hooks';
import { db, Walk } from '@/lib/db';
import { TrackPoint, calculateHaversineDistance } from '@/lib/geo';

// In-memory buffer to debounce frequent GPS updates to Dexie IndexedDB
const pendingPointsBuffer = new Map<string, TrackPoint[]>();
const debounceTimers = new Map<string, NodeJS.Timeout>();

/**
 * Returns the currently active walk (where endedAt is null), or undefined if none.
 */
export async function getActiveWalk(): Promise<Walk | undefined> {
  const walks = await db.walks.filter((w) => w.endedAt === null).toArray();
  if (walks.length === 0) return undefined;
  // If multiple exist (rare recovery state), take the latest one
  return walks.sort((a, b) => b.startedAt - a.startedAt)[0];
}

/**
 * Starts a new walk session in Dexie.
 */
export async function startWalkSession(mode: 'free' | 'loop' = 'free'): Promise<Walk> {
  const id = typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : `walk-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
  const newWalk: Walk = {
    id,
    startedAt: Date.now(),
    endedAt: null,
    mode,
    trackPoints: [],
    distance: 0,
  };

  await db.walks.add(newWalk);
  pendingPointsBuffer.set(id, []);
  return newWalk;
}

/**
 * Flushes any pending buffered track points for a walk directly into Dexie.
 */
export async function flushWalkBuffer(walkId: string): Promise<void> {
  const timer = debounceTimers.get(walkId);
  if (timer) {
    clearTimeout(timer);
    debounceTimers.delete(walkId);
  }

  const buffered = pendingPointsBuffer.get(walkId);
  if (!buffered || buffered.length === 0) return;

  const current = await db.walks.get(walkId);
  if (!current || current.endedAt !== null) {
    pendingPointsBuffer.delete(walkId);
    return;
  }

  let cumulativeDistance = current.distance || 0;
  let lastPoint = current.trackPoints.length > 0 ? current.trackPoints[current.trackPoints.length - 1] : null;

  for (const pt of buffered) {
    if (lastPoint) {
      cumulativeDistance += calculateHaversineDistance(lastPoint.lat, lastPoint.lng, pt.lat, pt.lng);
    }
    lastPoint = pt;
  }

  const updatedPoints = [...current.trackPoints, ...buffered];
  pendingPointsBuffer.set(walkId, []);

  await db.walks.update(walkId, {
    trackPoints: updatedPoints,
    distance: Math.round(cumulativeDistance),
  });
}

/**
 * Appends a verified track point to an active walk session, recalculating distance.
 * Buffers updates with a 1500ms debounce to prevent high-frequency IndexedDB write stutter.
 */
export async function appendTrackPointToSession(
  walkId: string,
  point: TrackPoint,
  options: { immediate?: boolean } = {}
): Promise<void> {
  const buffer = pendingPointsBuffer.get(walkId) || [];
  buffer.push(point);
  pendingPointsBuffer.set(walkId, buffer);

  if (options.immediate) {
    await flushWalkBuffer(walkId);
    return;
  }

  // Debounced write
  if (!debounceTimers.has(walkId)) {
    const timer = setTimeout(async () => {
      debounceTimers.delete(walkId);
      await flushWalkBuffer(walkId);
    }, 1500);
    debounceTimers.set(walkId, timer);
  }
}

/**
 * Finalizes an active walk session: flushes buffer, sets endedAt, and returns completed Walk.
 */
export async function endWalkSession(walkId: string): Promise<Walk | null> {
  await flushWalkBuffer(walkId);
  const endedAt = Date.now();
  await db.walks.update(walkId, { endedAt });
  const completed = await db.walks.get(walkId);
  return completed ?? null;
}

/**
 * Discards an active walk session permanently from Dexie (per D-15).
 */
export async function discardWalkSession(walkId: string): Promise<void> {
  const timer = debounceTimers.get(walkId);
  if (timer) {
    clearTimeout(timer);
    debounceTimers.delete(walkId);
  }
  pendingPointsBuffer.delete(walkId);
  await db.walks.delete(walkId);
}

export interface UseActiveWalkReturn {
  activeWalk: Walk | null | undefined;
  isActive: boolean;
  isResumed: boolean;
  dismissResumed: () => void;
  elapsedSeconds: number;
  distanceMeters: number;
  startWalk: (mode?: 'free' | 'loop') => Promise<Walk>;
  appendTrackPoint: (point: TrackPoint, options?: { immediate?: boolean }) => Promise<void>;
  endWalk: () => Promise<Walk | null>;
  discardWalk: () => Promise<void>;
}

export function useActiveWalk(): UseActiveWalkReturn {
  // Query active walk where endedAt is null using Dexie useLiveQuery
  const activeWalk = useLiveQuery(async () => {
    return getActiveWalk();
  }, []);

  const [isResumed, setIsResumed] = useState<boolean>(false);
  const [elapsedSeconds, setElapsedSeconds] = useState<number>(0);
  const initialCheckedRef = useRef<boolean>(false);
  const startedInThisMountRef = useRef<boolean>(false);

  // Detect auto-resumed walk session across tab reloads / background wakes (per D-04)
  useEffect(() => {
    if (initialCheckedRef.current || activeWalk === undefined) return;
    initialCheckedRef.current = true;

    if (activeWalk && !startedInThisMountRef.current) {
      setIsResumed(true);
    }
  }, [activeWalk]);

  const dismissResumed = useCallback(() => {
    setIsResumed(false);
  }, []);

  // Update elapsed seconds continuously based on startedAt timestamp
  useEffect(() => {
    if (!activeWalk || activeWalk.endedAt !== null) {
      setElapsedSeconds(0);
      return;
    }

    const updateTimer = () => {
      const elapsed = Math.max(0, Math.floor((Date.now() - activeWalk.startedAt) / 1000));
      setElapsedSeconds(elapsed);
    };

    updateTimer();
    const interval = setInterval(updateTimer, 1000);
    return () => clearInterval(interval);
  }, [activeWalk?.startedAt, activeWalk?.endedAt]);

  const startWalk = useCallback(async (mode: 'free' | 'loop' = 'free'): Promise<Walk> => {
    startedInThisMountRef.current = true;
    setIsResumed(false);
    return await startWalkSession(mode);
  }, []);

  const appendTrackPoint = useCallback(
    async (point: TrackPoint, options: { immediate?: boolean } = {}): Promise<void> => {
      if (!activeWalk?.id) return;
      await appendTrackPointToSession(activeWalk.id, point, options);
    },
    [activeWalk?.id]
  );

  const endWalk = useCallback(async (): Promise<Walk | null> => {
    if (!activeWalk?.id) return null;
    return await endWalkSession(activeWalk.id);
  }, [activeWalk?.id]);

  const discardWalk = useCallback(async (): Promise<void> => {
    if (!activeWalk?.id) return;
    await discardWalkSession(activeWalk.id);
  }, [activeWalk?.id]);

  return {
    activeWalk,
    isActive: Boolean(activeWalk),
    isResumed,
    dismissResumed,
    elapsedSeconds,
    distanceMeters: activeWalk?.distance ?? 0,
    startWalk,
    appendTrackPoint,
    endWalk,
    discardWalk,
  };
}

import 'fake-indexeddb/auto';
import { db } from '../lib/db';
import {
  startWalkSession,
  appendTrackPointToSession,
  endWalkSession,
  discardWalkSession,
  getActiveWalk,
  flushWalkBuffer,
} from '../hooks/use-active-walk';
import { TrackPoint } from '../lib/geo';

async function runTests() {
  console.log('🧪 Starting Active Walk Lifecycle & Auto-Resume Tests...\n');

  // Clean database before test
  await db.walks.clear();

  // Test 1: No active walk initially
  console.log('1. Testing initial state (no active walk)...');
  const initialActive = await getActiveWalk();
  if (initialActive !== undefined) {
    throw new Error(`Expected undefined active walk, got: ${JSON.stringify(initialActive)}`);
  }
  console.log('   ✅ Initial active walk is undefined');

  // Test 2: Start new walk session (WALK-01)
  console.log('2. Starting new walk session (WALK-01)...');
  const session = await startWalkSession('free');
  if (!session.id || typeof session.id !== 'string') {
    throw new Error('Expected session to have valid UUID id');
  }
  if (session.endedAt !== null) {
    throw new Error(`Expected session.endedAt to be null, got: ${session.endedAt}`);
  }
  if (session.trackPoints.length !== 0) {
    throw new Error('Expected new walk to have 0 trackPoints');
  }
  if (session.distance !== 0) {
    throw new Error('Expected new walk to have 0 distance');
  }
  console.log(`   ✅ Walk session created with ID: ${session.id}`);

  // Test 3: Auto-resume active walk lookup (WALK-02)
  console.log('3. Testing auto-resume lookup (WALK-02)...');
  const activeFound = await getActiveWalk();
  if (!activeFound || activeFound.id !== session.id) {
    throw new Error(`Expected to find active walk ${session.id}, got: ${activeFound?.id}`);
  }
  console.log('   ✅ Active walk session located in Dexie');

  // Test 4: Append track points and verify distance calculation (GPS-01, GPS-02)
  console.log('4. Appending track points and accumulating distance...');
  const point1: TrackPoint = {
    lat: 40.785091,
    lng: -73.968285,
    accuracy: 12,
    timestamp: Date.now(),
  };
  await appendTrackPointToSession(session.id, point1, { immediate: true });

  const point2: TrackPoint = {
    lat: 40.785500, // ~45.5 meters north
    lng: -73.968285,
    accuracy: 10,
    timestamp: Date.now() + 20000,
  };
  await appendTrackPointToSession(session.id, point2, { immediate: true });

  const updatedWalk = await db.walks.get(session.id);
  if (!updatedWalk) {
    throw new Error('Could not find updated walk record');
  }
  if (updatedWalk.trackPoints.length !== 2) {
    throw new Error(`Expected 2 track points, got: ${updatedWalk.trackPoints.length}`);
  }
  if (updatedWalk.distance < 40 || updatedWalk.distance > 50) {
    throw new Error(`Expected distance ~45m, got: ${updatedWalk.distance}m`);
  }
  console.log(`   ✅ Accumulated 2 points, distance: ${updatedWalk.distance}m`);

  // Test 5: End walk session (WALK-03)
  console.log('5. Ending walk session (WALK-03)...');
  const completed = await endWalkSession(session.id);
  if (!completed || completed.endedAt === null) {
    throw new Error('Expected completed walk to have non-null endedAt');
  }
  if (completed.distance !== updatedWalk.distance) {
    throw new Error('Expected distance to be preserved in completed walk');
  }
  console.log(`   ✅ Walk ended at: ${new Date(completed.endedAt).toISOString()}`);

  // Verify no active walk exists anymore
  const activeAfterEnd = await getActiveWalk();
  if (activeAfterEnd !== undefined) {
    throw new Error(`Expected no active walk after end, but found: ${activeAfterEnd.id}`);
  }
  console.log('   ✅ No active walk after ending session');

  // Test 6: Discard walk session (D-15)
  console.log('6. Testing discard short walk (D-15)...');
  const shortSession = await startWalkSession('free');
  const activeShort = await getActiveWalk();
  if (!activeShort || activeShort.id !== shortSession.id) {
    throw new Error('Failed to start short walk session');
  }

  await discardWalkSession(shortSession.id);
  const discardedInDb = await db.walks.get(shortSession.id);
  if (discardedInDb !== undefined) {
    throw new Error('Expected discarded walk to be removed from db.walks');
  }
  console.log('   ✅ Discarded walk purged cleanly from Dexie');

  console.log('\n🎉 ALL ACTIVE WALK TESTS PASSED SUCCESSFULLY!\n');
}

runTests().catch((err) => {
  console.error('\n❌ TEST RUN FAILED:', err);
  process.exit(1);
});

'use client';

import React, { useEffect, useRef, useState, useCallback, useImperativeHandle, forwardRef } from 'react';
import type { Map as MapLibreMap, Marker as MapLibreMarker, GeoJSONSource } from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';
import { calculateTrailBounds } from '@/lib/geo';
import { Navigation, Plus, Minus, Compass } from 'lucide-react';

export interface WalkMapProps {
  userPosition: {
    lat: number;
    lng: number;
    heading?: number | null;
    accuracy?: number;
  } | null;
  trackPoints: Array<{ lat: number; lng: number }>;
  isWalkActive?: boolean;
  className?: string;
  onFollowChange?: (isFollowing: boolean) => void;
}

export interface WalkMapRef {
  recenter: () => void;
  fitTrailBounds: (customPadding?: { top: number; bottom: number; left: number; right: number }) => void;
  getMapInstance: () => MapLibreMap | null;
}

export const WalkMap = forwardRef<WalkMapRef, WalkMapProps>(function WalkMap(
  {
    userPosition,
    trackPoints,
    isWalkActive = false,
    className = '',
    onFollowChange,
  },
  ref
) {
  const mapContainerRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<MapLibreMap | null>(null);
  const userMarkerRef = useRef<MapLibreMarker | null>(null);
  const markerElRef = useRef<HTMLDivElement | null>(null);
  const headingConeElRef = useRef<HTMLDivElement | null>(null);

  const [isFollowing, setIsFollowing] = useState<boolean>(true);
  const [mapLoaded, setMapLoaded] = useState<boolean>(false);
  const [compassBearing, setCompassBearing] = useState<number>(0);

  // Update follow state and notify parent
  const updateFollowing = useCallback(
    (following: boolean) => {
      setIsFollowing(following);
      onFollowChange?.(following);
    },
    [onFollowChange]
  );

  // Recenter camera to user position
  const handleRecenter = useCallback(() => {
    if (!mapRef.current || !userPosition) return;
    updateFollowing(true);
    mapRef.current.flyTo({
      center: [userPosition.lng, userPosition.lat],
      zoom: Math.max(mapRef.current.getZoom(), 16),
      essential: true,
      duration: 1000,
    });
  }, [userPosition, updateFollowing]);

  // Fit camera bounds to the complete trail
  const handleFitTrailBounds = useCallback(
    (customPadding = { top: 96, bottom: 240, left: 48, right: 48 }) => {
      if (!mapRef.current || trackPoints.length === 0) return;
      const bounds = calculateTrailBounds(trackPoints);
      if (bounds) {
        updateFollowing(false);
        mapRef.current.fitBounds(bounds, {
          padding: customPadding,
          maxZoom: 17,
          duration: 1200,
        });
      }
    },
    [trackPoints, updateFollowing]
  );

  // Expose methods via ref
  useImperativeHandle(
    ref,
    () => ({
      recenter: handleRecenter,
      fitTrailBounds: handleFitTrailBounds,
      getMapInstance: () => mapRef.current,
    }),
    [handleRecenter, handleFitTrailBounds]
  );

  // Zoom controls
  const handleZoomIn = useCallback(() => {
    mapRef.current?.zoomIn({ duration: 300 });
  }, []);

  const handleZoomOut = useCallback(() => {
    mapRef.current?.zoomOut({ duration: 300 });
  }, []);

  // Reset rotation to North
  const handleResetNorth = useCallback(() => {
    mapRef.current?.resetNorthPitch({ duration: 500 });
    setCompassBearing(0);
  }, []);

  // Initialize MapLibre GL
  useEffect(() => {
    if (!mapContainerRef.current) return;

    let isMounted = true;

    async function initMap() {
      const maplibreglModule = await import('maplibre-gl');
      const maplibregl = (maplibreglModule as any).default || maplibreglModule;

      if (!isMounted || !mapContainerRef.current) return;

      const initialCenter: [number, number] = userPosition
        ? [userPosition.lng, userPosition.lat]
        : [-73.968, 40.785]; // Default fallback

      const map = new maplibregl.Map({
        container: mapContainerRef.current,
        style: 'https://tiles.openfreemap.org/styles/liberty',
        center: initialCenter,
        zoom: 16,
        attributionControl: false,
      });

      // User break-to-pan detection (per D-09)
      const onUserInteraction = () => {
        updateFollowing(false);
      };

      map.on('dragstart', onUserInteraction);
      map.on('rotatestart', onUserInteraction);
      map.on('pitchstart', onUserInteraction);
      map.on('rotate', () => {
        setCompassBearing(Math.round(map.getBearing()));
      });

      map.on('load', () => {
        if (!isMounted) return;

        // 1. Initialize GeoJSON source for trail polyline
        map.addSource('walk-trail', {
          type: 'geojson',
          data: {
            type: 'Feature',
            properties: {},
            geometry: {
              type: 'LineString',
              coordinates: trackPoints.map((pt) => [pt.lng, pt.lat]),
            },
          },
        });

        // 2. Add line layer styled with Tangerin Dream terracotta (per D-11, GPS-02)
        map.addLayer({
          id: 'walk-trail-layer',
          type: 'line',
          source: 'walk-trail',
          layout: {
            'line-join': 'round',
            'line-cap': 'round',
          },
          paint: {
            'line-color': '#F35C2B', // Terracotta primary
            'line-width': 4,
            'line-opacity': 0.95,
          },
        });

        // 3. Create custom HTML marker for user location (per D-10)
        const markerEl = document.createElement('div');
        markerEl.className = 'treads-user-marker relative flex items-center justify-center w-8 h-8 pointer-events-none';

        // Continuous radar pulse ring
        const pulseRing = document.createElement('div');
        pulseRing.className = 'absolute inset-0 rounded-full bg-[#F35C2B]/30 animate-ping';
        markerEl.appendChild(pulseRing);

        // Core halo
        const halo = document.createElement('div');
        halo.className = 'absolute w-6 h-6 rounded-full bg-[#F35C2B]/40';
        markerEl.appendChild(halo);

        // Solid terracotta dot
        const dot = document.createElement('div');
        dot.className = 'relative w-3.5 h-3.5 rounded-full bg-[#F35C2B] border-2 border-white shadow-md';
        markerEl.appendChild(dot);

        // Heading directional arrow / cone
        const headingCone = document.createElement('div');
        headingCone.className = 'absolute -top-3 w-0 h-0 border-l-[4px] border-l-transparent border-r-[4px] border-r-transparent border-b-[8px] border-b-[#F35C2B] transition-transform duration-200';
        headingCone.style.display = 'none';
        markerEl.appendChild(headingCone);

        markerElRef.current = markerEl;
        headingConeElRef.current = headingCone;

        const marker = new maplibregl.Marker({
          element: markerEl,
          anchor: 'center',
        });

        if (userPosition) {
          marker.setLngLat([userPosition.lng, userPosition.lat]).addTo(map);
        }

        userMarkerRef.current = marker;
        mapRef.current = map;
        setMapLoaded(true);
      });
    }

    initMap();

    return () => {
      isMounted = false;
      if (userMarkerRef.current) {
        userMarkerRef.current.remove();
        userMarkerRef.current = null;
      }
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
      }
    };
  }, []); // Run once on mount

  // Sync user marker position & heading
  useEffect(() => {
    if (!mapLoaded || !mapRef.current || !userPosition) return;

    if (!userMarkerRef.current) {
      // If not yet added, create or attach
      return;
    }

    userMarkerRef.current.setLngLat([userPosition.lng, userPosition.lat]);

    // Update heading cone rotation if available
    if (headingConeElRef.current) {
      if (userPosition.heading != null && !isNaN(userPosition.heading)) {
        headingConeElRef.current.style.display = 'block';
        headingConeElRef.current.style.transform = `rotate(${userPosition.heading}deg)`;
      } else {
        headingConeElRef.current.style.display = 'none';
      }
    }

    // Auto-follow camera if enabled (per D-09)
    if (isFollowing) {
      mapRef.current.easeTo({
        center: [userPosition.lng, userPosition.lat],
        duration: 800,
      });
    }
  }, [userPosition, isFollowing, mapLoaded]);

  // Sync trail polyline GeoJSON data
  useEffect(() => {
    if (!mapLoaded || !mapRef.current) return;

    const source = mapRef.current.getSource('walk-trail') as GeoJSONSource | undefined;
    if (source) {
      source.setData({
        type: 'Feature',
        properties: {},
        geometry: {
          type: 'LineString',
          coordinates: trackPoints.map((pt) => [pt.lng, pt.lat]),
        },
      });
    }
  }, [trackPoints, mapLoaded]);

  return (
    <div className={`relative w-full h-full overflow-hidden bg-background ${className}`}>
      {/* Map container */}
      <div ref={mapContainerRef} className="absolute inset-0 w-full h-full" />

      {/* Floating thumb-accessible control stack on right margin (per D-12) */}
      <div className="absolute right-4 top-24 z-20 flex flex-col items-center gap-2 select-none">
        {/* Recenter Button (shows active tint if following) */}
        <button
          type="button"
          onClick={handleRecenter}
          aria-label="Recenter map to current location"
          className={`flex items-center justify-center w-12 h-12 rounded-full backdrop-blur-md border shadow-md transition-all active:scale-95 ${
            isFollowing
              ? 'bg-[#F35C2B] text-white border-[#F35C2B]'
              : 'bg-background/85 text-foreground border-border/80 hover:bg-background'
          }`}
        >
          <Navigation className={`w-5 h-5 ${isFollowing ? 'fill-current' : ''}`} />
        </button>

        {/* Zoom In (+) */}
        <button
          type="button"
          onClick={handleZoomIn}
          aria-label="Zoom in"
          className="flex items-center justify-center w-12 h-12 rounded-full bg-background/85 backdrop-blur-md border border-border/80 text-foreground shadow-md transition-all hover:bg-background active:scale-95"
        >
          <Plus className="w-5 h-5" />
        </button>

        {/* Zoom Out (-) */}
        <button
          type="button"
          onClick={handleZoomOut}
          aria-label="Zoom out"
          className="flex items-center justify-center w-12 h-12 rounded-full bg-background/85 backdrop-blur-md border border-border/80 text-foreground shadow-md transition-all hover:bg-background active:scale-95"
        >
          <Minus className="w-5 h-5" />
        </button>

        {/* North Compass Reset */}
        <button
          type="button"
          onClick={handleResetNorth}
          aria-label="Reset orientation north"
          className="flex items-center justify-center w-12 h-12 rounded-full bg-background/85 backdrop-blur-md border border-border/80 text-foreground shadow-md transition-all hover:bg-background active:scale-95"
          style={{ transform: `rotate(${-compassBearing}deg)` }}
        >
          <Compass className="w-5 h-5 text-[#F35C2B]" />
        </button>
      </div>

      {/* Micro-legend chip for trail path (per D-11) */}
      {isWalkActive && trackPoints.length > 0 && (
        <div className="absolute left-4 bottom-28 z-20 pointer-events-none">
          <div className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-background/80 backdrop-blur-md border border-border/60 shadow-xs text-xs text-muted-foreground">
            <span className="w-3.5 h-1 rounded-full bg-[#F35C2B]" />
            <span className="font-mono text-[11px] font-medium tracking-tight">Approximate path</span>
          </div>
        </div>
      )}
    </div>
  );
});

