'use client';

import React from 'react';
import { formatDistance, formatDuration } from '@/lib/geo';
import { GpsSignalStatus } from '@/hooks/use-geolocation';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { AlertCircle, AlertTriangle, CheckCircle2, Loader2, Navigation2, X } from 'lucide-react';

export interface WalkHudProps {
  durationSeconds: number;
  distanceMeters: number;
  gpsStatus: GpsSignalStatus;
  accuracy?: number;
  onRequestLocation?: () => void;
  isResumed?: boolean;
  onDismissResumed?: () => void;
}

export function WalkHud({
  durationSeconds,
  distanceMeters,
  gpsStatus,
  accuracy,
  onRequestLocation,
  isResumed = false,
  onDismissResumed,
}: WalkHudProps) {
  return (
    <div className="absolute top-4 inset-x-0 z-30 flex flex-col items-center gap-2 px-4 pointer-events-none">
      {/* Auto-resumed Toast Pill (per D-04) */}
      {isResumed && (
        <div className="pointer-events-auto flex items-center gap-2 px-3.5 py-1.5 rounded-full bg-background/90 backdrop-blur-md border border-[#F35C2B]/40 shadow-md text-xs font-medium text-foreground animate-in fade-in slide-in-from-top-2 duration-300">
          <Navigation2 className="w-3.5 h-3.5 text-[#F35C2B] fill-current" />
          <span>Active walk resumed</span>
          {onDismissResumed && (
            <button
              type="button"
              onClick={onDismissResumed}
              aria-label="Dismiss notice"
              className="ml-1 p-0.5 rounded-full hover:bg-muted text-muted-foreground hover:text-foreground"
            >
              <X className="w-3 h-3" />
            </button>
          )}
        </div>
      )}

      {/* Permission Denied Top Alert Banner (per D-08) */}
      {gpsStatus === 'denied' && (
        <div className="pointer-events-auto w-full max-w-md flex items-center justify-between gap-3 p-3 rounded-xl bg-destructive/15 backdrop-blur-md border border-destructive/30 text-destructive text-xs shadow-lg animate-in fade-in slide-in-from-top-2">
          <div className="flex items-center gap-2">
            <AlertCircle className="w-4 h-4 shrink-0" />
            <span className="font-medium leading-tight">
              Location signal unavailable. Enable GPS permissions in your browser to record your walk.
            </span>
          </div>
          {onRequestLocation && (
            <Button
              variant="destructive"
              size="sm"
              onClick={onRequestLocation}
              className="h-7 px-2.5 text-xs font-semibold shrink-0 cursor-pointer"
            >
              Re-enable Location
            </Button>
          )}
        </div>
      )}

      {/* Floating Glassmorphism Main HUD Bar (per D-01, D-02) */}
      <div className="pointer-events-auto flex items-center justify-between gap-3 px-4 py-2.5 rounded-full bg-background/85 backdrop-blur-md border border-border/70 shadow-lg min-w-[280px] max-w-sm">
        {/* Timer */}
        <div className="flex flex-col items-start">
          <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-mono">
            Time
          </span>
          <span className="font-mono text-base font-semibold tabular-nums text-foreground">
            {formatDuration(durationSeconds)}
          </span>
        </div>

        {/* Vertical divider */}
        <div className="w-[1px] h-6 bg-border/70" />

        {/* Distance */}
        <div className="flex flex-col items-start">
          <span className="text-[10px] uppercase tracking-wider text-muted-foreground font-mono">
            Distance
          </span>
          <span className="font-mono text-base font-semibold tabular-nums text-foreground">
            {formatDistance(distanceMeters)}
          </span>
        </div>

        {/* Vertical divider */}
        <div className="w-[1px] h-6 bg-border/70" />

        {/* GPS Signal Status Chip (per D-02, D-05) */}
        <div className="flex items-center">
          {gpsStatus === 'live' && (
            <Badge
              variant="outline"
              className="gap-1.5 bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border-emerald-500/30 text-[11px] font-mono font-medium py-0.5 px-2"
            >
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
              Live
            </Badge>
          )}

          {gpsStatus === 'searching' && (
            <Badge
              variant="outline"
              className="gap-1.5 bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/30 text-[11px] font-mono font-medium py-0.5 px-2"
            >
              <Loader2 className="w-3 h-3 animate-spin text-amber-500" />
              Searching
            </Badge>
          )}

          {gpsStatus === 'weak' && (
            <Badge
              variant="outline"
              className="gap-1 bg-amber-500/15 text-amber-600 dark:text-amber-400 border-amber-500/40 text-[11px] font-mono font-medium py-0.5 px-2"
            >
              <AlertTriangle className="w-3 h-3 text-amber-500" />
              Weak GPS {accuracy ? `±${Math.round(accuracy)}m` : ''}
            </Badge>
          )}

          {gpsStatus === 'denied' && (
            <Badge
              variant="destructive"
              className="text-[11px] font-mono font-medium py-0.5 px-2"
            >
              Denied
            </Badge>
          )}

          {gpsStatus === 'error' && (
            <Badge
              variant="destructive"
              className="text-[11px] font-mono font-medium py-0.5 px-2"
            >
              Error
            </Badge>
          )}

          {gpsStatus === 'idle' && (
            <Badge
              variant="outline"
              className="text-[11px] font-mono text-muted-foreground py-0.5 px-2"
            >
              Idle
            </Badge>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { Square, Camera } from 'lucide-react';

export interface WalkControlsProps {
  onEndWalk: () => void;
  onCameraClick?: () => void;
  disabled?: boolean;
}

const HOLD_DURATION_MS = 1500;

export function WalkControls({
  onEndWalk,
  onCameraClick,
  disabled = false,
}: WalkControlsProps) {
  const [holdProgress, setHoldProgress] = useState<number>(0);
  const [isHolding, setIsHolding] = useState<boolean>(false);

  const startTimeRef = useRef<number | null>(null);
  const animationFrameRef = useRef<number | null>(null);
  const hasTriggeredRef = useRef<boolean>(false);

  const cancelHold = useCallback(() => {
    setIsHolding(false);
    startTimeRef.current = null;
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = null;
    }
    setHoldProgress(0);
  }, []);

  const startHold = useCallback(
    (e: React.SyntheticEvent) => {
      if (disabled) return;
      // Prevent context menus on mobile long-press
      if (e.type === 'touchstart') {
        // e.preventDefault is handled if needed
      }

      setIsHolding(true);
      hasTriggeredRef.current = false;
      startTimeRef.current = performance.now();

      const tick = (now: number) => {
        if (!startTimeRef.current) return;
        const elapsed = now - startTimeRef.current;
        const progress = Math.min(100, (elapsed / HOLD_DURATION_MS) * 100);
        setHoldProgress(progress);

        if (progress >= 100 && !hasTriggeredRef.current) {
          hasTriggeredRef.current = true;
          cancelHold();
          // Haptic feedback if supported
          if (typeof navigator !== 'undefined' && 'vibrate' in navigator) {
            try {
              navigator.vibrate?.(50);
            } catch {
              // Ignore haptic errors
            }
          }
          onEndWalk();
          return;
        }

        animationFrameRef.current = requestAnimationFrame(tick);
      };

      animationFrameRef.current = requestAnimationFrame(tick);
    },
    [disabled, onEndWalk, cancelHold]
  );

  useEffect(() => {
    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current);
      }
    };
  }, []);

  // Calculate SVG stroke offset for circular progress (circle r=26, circumference = 2 * PI * 26 ≈ 163.36)
  const radius = 26;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (holdProgress / 100) * circumference;

  return (
    <div className="absolute bottom-8 inset-x-0 z-30 flex items-center justify-center gap-6 px-4 pointer-events-none select-none">
      <div className="pointer-events-auto flex items-center gap-5 p-2 rounded-full bg-background/85 backdrop-blur-md border border-border/70 shadow-xl">
        {/* Camera Capture Trigger (Scaffold for Phase 3) */}
        <button
          type="button"
          onClick={onCameraClick}
          aria-label="Capture specimen"
          className="flex items-center justify-center w-14 h-14 rounded-full bg-muted/80 hover:bg-muted text-foreground border border-border/60 transition-transform active:scale-95 shadow-sm cursor-pointer"
        >
          <Camera className="w-6 h-6 text-[#F35C2B]" />
        </button>

        {/* Hold-to-Confirm "End Walk" Action (per D-13) */}
        <div className="relative flex items-center justify-center">
          {/* Circular SVG Progress Ring */}
          <svg
            className="absolute inset-0 w-16 h-16 pointer-events-none -rotate-90"
            viewBox="0 0 64 64"
          >
            {/* Background track */}
            <circle
              cx="32"
              cy="32"
              r={radius}
              className="text-border/40"
              strokeWidth="3.5"
              stroke="currentColor"
              fill="transparent"
            />
            {/* Animated progress ring */}
            <circle
              cx="32"
              cy="32"
              r={radius}
              className="text-[#DC2626] transition-all"
              strokeWidth="4"
              strokeDasharray={circumference}
              strokeDashoffset={strokeDashoffset}
              strokeLinecap="round"
              stroke="currentColor"
              fill="transparent"
            />
          </svg>

          {/* Core Button (min 48px touch target: w-14 h-14 = 56px) */}
          <button
            type="button"
            aria-label="Hold button to finalize and save your walk session"
            disabled={disabled}
            onMouseDown={startHold}
            onMouseUp={cancelHold}
            onMouseLeave={cancelHold}
            onTouchStart={startHold}
            onTouchEnd={cancelHold}
            onTouchCancel={cancelHold}
            className={`relative flex items-center justify-center w-14 h-14 rounded-full transition-all duration-150 cursor-pointer shadow-md active:scale-95 ${
              isHolding
                ? 'bg-destructive text-destructive-foreground scale-95 shadow-destructive/20'
                : 'bg-destructive/90 hover:bg-destructive text-white'
            }`}
          >
            <Square className="w-5 h-5 fill-current" />
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import React from 'react';
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
  SheetFooter,
} from '@/components/ui/sheet';
import { Button } from '@/components/ui/button';
import { formatDistance, formatDuration } from '@/lib/geo';
import { Clock, MapPin, Gauge, Leaf, ArrowRight } from 'lucide-react';
import Link from 'next/link';

export interface WalkSummarySheetProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  durationSeconds: number;
  distanceMeters: number;
  speciesCount?: number;
  onDone: () => void;
  onViewJournal?: () => void;
}

export function WalkSummarySheet({
  open,
  onOpenChange,
  durationSeconds,
  distanceMeters,
  speciesCount = 0,
  onDone,
  onViewJournal,
}: WalkSummarySheetProps) {
  // Compute average pace (minutes per km)
  let paceDisplay = '--:-- /km';
  if (distanceMeters >= 50 && durationSeconds > 0) {
    const km = distanceMeters / 1000;
    const paceSecondsPerKm = durationSeconds / km;
    const paceMin = Math.floor(paceSecondsPerKm / 60);
    const paceSec = Math.floor(paceSecondsPerKm % 60);
    paceDisplay = `${paceMin}:${paceSec.toString().padStart(2, '0')} /km`;
  }

  const speciesLabel = speciesCount === 1 ? '1 species recorded' : `${speciesCount} species recorded`;

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="bottom"
        className="max-w-md mx-auto rounded-t-3xl border-t border-border/80 bg-card p-6 pb-8 shadow-2xl"
      >
        <SheetHeader className="text-left space-y-1 pb-2">
          <div className="flex items-center gap-2">
            <span className="w-2.5 h-2.5 rounded-full bg-[#F35C2B]" />
            <SheetTitle className="text-xl font-semibold tracking-tight text-foreground font-sans">
              Walk Complete
            </SheetTitle>
          </div>
          <SheetDescription className="text-sm text-muted-foreground">
            Summary of your outdoor trail session and field observations.
          </SheetDescription>
        </SheetHeader>

        {/* Big Total Distance Headline (Display 28px per UI-SPEC) */}
        <div className="py-3">
          <span className="text-xs uppercase tracking-wider text-muted-foreground font-mono">
            Total Distance
          </span>
          <div className="text-3xl font-bold tracking-tight text-[#F35C2B] font-sans">
            {formatDistance(distanceMeters)}
          </div>
        </div>

        {/* 4-Cell Stats Grid (lg 24px cell padding per UI-SPEC) */}
        <div className="grid grid-cols-2 gap-3 py-2">
          {/* Duration */}
          <div className="flex flex-col p-3 rounded-xl bg-muted/50 border border-border/60">
            <div className="flex items-center gap-1.5 text-xs text-muted-foreground mb-1">
              <Clock className="w-3.5 h-3.5 text-primary" />
              <span>Duration</span>
            </div>
            <span className="font-mono text-base font-semibold text-foreground">
              {formatDuration(durationSeconds)}
            </span>
          </div>

          {/* Average Pace */}
          <div className="flex flex-col p-3 rounded-xl bg-muted/50 border border-border/60">
            <div className="flex items-center gap-1.5 text-xs text-muted-foreground mb-1">
              <Gauge className="w-3.5 h-3.5 text-primary" />
              <span>Avg Pace</span>
            </div>
            <span className="font-mono text-base font-semibold text-foreground">
              {paceDisplay}
            </span>
          </div>

          {/* Species Count */}
          <div className="flex flex-col p-3 rounded-xl bg-muted/50 border border-border/60 col-span-2">
            <div className="flex items-center gap-1.5 text-xs text-muted-foreground mb-1">
              <Leaf className="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400" />
              <span>Field Identifications</span>
            </div>
            <span className="font-mono text-base font-semibold text-foreground">
              {speciesLabel}
            </span>
          </div>
        </div>

        {/* Action Buttons (per D-16) */}
        <SheetFooter className="flex flex-col gap-2 pt-4 sm:flex-col sm:space-x-0">
          {/* Primary "Done" action resets /walk to ready state */}
          <Button
            type="button"
            onClick={onDone}
            className="w-full h-12 text-sm font-semibold bg-[#F35C2B] hover:bg-[#F35C2B]/90 text-white rounded-xl shadow-md cursor-pointer"
          >
            Done
          </Button>

          {/* Secondary "View in Journal" link */}
          {onViewJournal ? (
            <Button
              type="button"
              variant="outline"
              onClick={onViewJournal}
              className="w-full h-11 text-xs font-semibold rounded-xl border-border/80 hover:bg-muted cursor-pointer"
            >
              View in Journal
              <ArrowRight className="w-3.5 h-3.5 ml-1" />
            </Button>
          ) : (
            <Button
              asChild
              variant="outline"
              className="w-full h-11 text-xs font-semibold rounded-xl border-border/80 hover:bg-muted cursor-pointer"
            >
              <Link href="/journal" onClick={onDone}>
                View in Journal
                <ArrowRight className="w-3.5 h-3.5 ml-1" />
              </Link>
            </Button>
          )}
        </SheetFooter>
      </SheetContent>
    </Sheet>
  );
}

'use client';

import React from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { AlertTriangle } from 'lucide-react';

export interface WalkDiscardDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onConfirmDiscard: () => void;
  onSaveAnyway: () => void;
}

export function WalkDiscardDialog({
  open,
  onOpenChange,
  onConfirmDiscard,
  onSaveAnyway,
}: WalkDiscardDialogProps) {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-sm rounded-2xl border-border bg-card p-6 shadow-xl">
        <DialogHeader className="text-left space-y-2">
          <div className="flex items-center gap-2 text-destructive">
            <div className="p-2 rounded-full bg-destructive/10">
              <AlertTriangle className="w-5 h-5 text-destructive" />
            </div>
            <DialogTitle className="text-lg font-semibold tracking-tight text-foreground font-sans">
              Discard Walk
            </DialogTitle>
          </div>
          <DialogDescription className="text-sm text-muted-foreground pt-1">
            Walk was under 1 minute. Discard this test session without saving?
          </DialogDescription>
        </DialogHeader>

        <DialogFooter className="flex flex-col gap-2 pt-4 sm:flex-col sm:space-x-0">
          {/* Primary destructive action */}
          <Button
            type="button"
            variant="destructive"
            onClick={onConfirmDiscard}
            className="w-full h-11 text-xs font-semibold rounded-xl cursor-pointer"
          >
            Discard Walk
          </Button>

          {/* Secondary preserve action */}
          <Button
            type="button"
            variant="outline"
            onClick={onSaveAnyway}
            className="w-full h-11 text-xs font-semibold rounded-xl border-border/80 hover:bg-muted cursor-pointer"
          >
            Save Anyway
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

